56c-7e24-9e1a-edc002ffed8a","description":"The Upanishads","correct_answer":false},{"id":"01a218eb-556c-7414-b04d-dfa71fb25c6c","description":"The Ramayana","correct_answer":false},{"id":"01a218eb-556c-7316-bd13-fe85895c277b","description":"The Puranas","correct_answer":false}]},{"id":"01a218eb-556c-7931-bebd-17fbb160ee1b","locale":"en-US","category":"01a21312-b489-7dd6-93ca-116c8464996a","question":"What is the name of the Islamic call to prayer?","difficulty":3,"explanation":"The adhan is the call to prayer recited by the muezzin to summon Muslims.","alternatives":[{"id":"01a218eb-556c-73e5-a1bc-1a42535381eb","description":"Adhan","correct_answer":true},{"id":"01a218eb-556c-74e9-a698-1f626d5a8c0d","description":"Iqama","correct_answer":false},{"id":"01a218eb-556c-7ed3-bd6b-657376f6dea6","description":"Niqab","correct_answer":false},{"id":"01a218eb-556c-7de0-b7ba-8e63127fd0a4","description":"Wudu","correct_answer":false}]},{"id":"01a218eb-556c-7967-acd5-2965e0cbe729","locale":"en-US","category":"01a21312-b489-7dd6-93ca-116c8464996a","question":"What is the name of the Hindu festival of colors?","difficulty":3,"explanation":"Holi is also known as the spring festival; many communities light bonfires on the eve of the celebration.","alternatives":[{"id":"01a218eb-556c-7b8a-b924-f252f38c845a","description":"Holi","correct_answer":true},{"id":"01a218eb-556c-7aae-8e01-3903d417eb34","description":"Diwali","correct_answer":false},{"id":"01a218eb-556c-7fd1-b8a3-8fd59906e4d9","description":"Dusshera","correct_answer":false},{"id":"01a218eb-556c-7aec-91e2-2c04729c0f57","description":"Navaratri","correct_answer":false}]},{"id":"01a218eb-556c-7e85-8d9a-2c7046911a10","locale":"en-US","category":"01a21312-b489-7dd6-93ca-116c8464996a","question":"Which Latin music legend is known for her signature fruity hat?","difficulty":3,"explanation":"Carmen Miranda was a Brazilian singer and actress who became an international star in Hollywood musicals.","alternatives":[{"id":"01a218eb-556c